css:
.d-quantity-stepper{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-quantity-stepper *,.d-quantity-stepper *::before,.d-quantity-stepper *::after{box-sizing:border-box}
.d-quantity-stepper [hidden]{display:none!important}
.d-quantity-stepper .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-quantity-stepper .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-quantity-stepper label{display:block;margin:8px 0}
.d-quantity-stepper input,.d-quantity-stepper select,.d-quantity-stepper textarea,.d-quantity-stepper button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-quantity-stepper input:not([type=checkbox]):not([type=radio]),.d-quantity-stepper select,.d-quantity-stepper textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-quantity-stepper button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-quantity-stepper button:disabled{opacity:.5;cursor:default}
.d-quantity-stepper :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-quantity-stepper [aria-invalid=true]{border-color:var(--warn)!important}
.d-quantity-stepper .d-scroll{max-width:100%;overflow:auto}
.d-quantity-stepper table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-quantity-stepper th,.d-quantity-stepper td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-quantity-stepper caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-quantity-stepper progress{width:100%;accent-color:var(--ink)}
.d-quantity-stepper pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-quantity-stepper h3,.d-quantity-stepper p{margin:8px 0}
.d-quantity-stepper [aria-pressed=true],.d-quantity-stepper [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-quantity-stepper .d-grow{flex:1;min-width:100px}
.d-quantity-stepper summary{cursor:pointer;padding:6px 0}
.d-quantity-stepper ul,.d-quantity-stepper ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const field=q('[data-value]');const sync=()=>{let n=Number(field.value);if(!Number.isFinite(n))n=0;n=Math.min(10,Math.max(0,Math.round(n*2)/2));field.value=String(n);q('[data-minus]').disabled=n<=0;q('[data-plus]').disabled=n>=10;say(n+' 小时');};q('[data-minus]').onclick=()=>{field.stepDown();sync();};q('[data-plus]').onclick=()=>{field.stepUp();sync();};field.onchange=sync;sync();})(root, q, qa, say);
}
